package identity

import (
	"context"
	"database/sql"
	"fmt"
)

// Per-user state transitions (accounts design.md §4/D7): the one-shot
// legacy-row adoption and DeleteUser's cascade. Both are single
// transactions — a partial adopt or a half-deleted user is never visible.

// The legacy ledger slot: every row written before accounts (and every row
// still written by a legacy principal) lands in user_id=0.
const legacySlot = 0

// AdoptLegacyRows merges the user_id=0 legacy ledger slots into the named
// user's slots — the EXPLICIT admin action (design D7: never automatic
// seed-on-first-login), one transaction per call. It claims ALL slot-0
// rows: each is either moved or superseded, so slot 0 drains completely
// and a rerun is a no-op. NEWER-WINS per item: updated_at is the
// playback_progress comparator, completed_at the watched_items one; a TIE
// keeps the user's existing row (incumbent preference). An unknown userID
// refuses (wrapped sql.ErrNoRows) before anything is written — adoption
// never mints dangling rows.
func (s *Service) AdoptLegacyRows(ctx context.Context, userID int64) error {
	tx, err := s.st.DB().BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("identity: adopt legacy tx: %w", err)
	}
	defer func() { _ = tx.Rollback() }()

	var exists int
	if err := tx.QueryRowContext(ctx,
		`SELECT EXISTS(SELECT 1 FROM users WHERE id = ?)`, userID).Scan(&exists); err != nil {
		return fmt.Errorf("identity: adopt legacy probe user: %w", err)
	}
	if exists == 0 {
		return fmt.Errorf("identity: adopt legacy: unknown user: %w", sql.ErrNoRows)
	}

	// Move slot-0 rows that beat (or lack) a user-row counterpart; the
	// NOT EXISTS >= comparison also drops ties in favor of the incumbent.
	// The upsert arm covers the newer-legacy-wins case: the user's slot
	// already holds a row for that item, so the winner's values overwrite
	// it in place.
	const adoptProgress = `INSERT INTO playback_progress (user_id, item_id, position_seconds, updated_at)
SELECT ?, p0.item_id, p0.position_seconds, p0.updated_at
FROM playback_progress p0
WHERE p0.user_id = ?
  AND NOT EXISTS (
    SELECT 1 FROM playback_progress pu
    WHERE pu.user_id = ? AND pu.item_id = p0.item_id
      AND pu.updated_at >= p0.updated_at)
ON CONFLICT (user_id, item_id) DO UPDATE SET
  position_seconds = excluded.position_seconds,
  updated_at = excluded.updated_at`
	if _, err := tx.ExecContext(ctx, adoptProgress, userID, legacySlot, userID); err != nil {
		return fmt.Errorf("identity: adopt legacy progress: %w", err)
	}
	const adoptWatched = `INSERT INTO watched_items (user_id, item_id, library_id, series_relative_path, completed_at, applied_at)
SELECT ?, w0.item_id, w0.library_id, w0.series_relative_path, w0.completed_at, w0.applied_at
FROM watched_items w0
WHERE w0.user_id = ?
  AND NOT EXISTS (
    SELECT 1 FROM watched_items wu
    WHERE wu.user_id = ? AND wu.item_id = w0.item_id
      AND wu.completed_at >= w0.completed_at)
ON CONFLICT (user_id, item_id) DO UPDATE SET
  library_id = excluded.library_id,
  series_relative_path = excluded.series_relative_path,
  completed_at = excluded.completed_at,
  applied_at = excluded.applied_at`
	if _, err := tx.ExecContext(ctx, adoptWatched, userID, legacySlot, userID); err != nil {
		return fmt.Errorf("identity: adopt legacy watched: %w", err)
	}

	// Drain the claimed slot: every slot-0 row was either adopted above or
	// superseded by the user's newer row. What a concurrent legacy principal
	// writes AFTER this commit lands in slot 0 fresh and stays (the adopt
	// is one-shot, not a subscription).
	for _, q := range []string{
		`DELETE FROM playback_progress WHERE user_id = ?`,
		`DELETE FROM watched_items WHERE user_id = ?`,
	} {
		if _, err := tx.ExecContext(ctx, q, legacySlot); err != nil {
			return fmt.Errorf("identity: adopt legacy drain: %w", err)
		}
	}
	return tx.Commit()
}
